#!/usr/bin/env node
// Memory CLI (Phase 6). Dependency-free.
//   mem index            regenerate docs/memory/INDEX.md from lesson frontmatter
//   mem report           regenerate docs/memory/LAST_REPORT.md (newest entry of each session log)
//   mem find <topic>     print ONLY lessons whose triggers/title match — retrieval, not reading
//   mem new "<title>" --triggers a,b --files p1,p2 --cost "..." --evidence "..."   write one lesson file
//   mem check            budget + missing files + malformed frontmatter + conflict markers; exit 1 on errors
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { parseFrontmatter } from './lib/fm.mjs';
import { currentRole } from './lib/policy.mjs';

const REQUIRED = ['id', 'date', 'session', 'title', 'triggers', 'files', 'cost', 'evidence', 'status'];

export function lessons(root) {
  const dir = join(root, 'docs', 'memory', 'lessons');
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith('.md')).sort().map((f) => {
    const path = join(dir, f);
    const { data } = parseFrontmatter(readFileSync(path, 'utf8'));
    return { file: relative(root, path).replace(/\\/g, '/'), data };
  });
}

function walk(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const e of readdirSync(dir)) {
    if (e === 'node_modules' || e === '.git' || e === 'vendor') continue;
    const p = join(dir, e);
    if (statSync(p).isDirectory()) walk(p, out); else out.push(p);
  }
  return out;
}

export function check(root) {
  const errors = [];
  const warnings = [];
  const ids = new Map();
  for (const { file, data } of lessons(root)) {
    if (!data) { errors.push(`${file}: no frontmatter`); continue; }
    for (const k of REQUIRED) if (data[k] === undefined || data[k] === '') errors.push(`${file}: missing "${k}"`);
    if (data.id) {
      if (ids.has(data.id)) errors.push(`${file}: duplicate id ${data.id} (also ${ids.get(data.id)})`);
      ids.set(data.id, file);
    }
    if (data.status && data.status !== 'live' && !/^superseded_by:?/.test(String(data.status)) && !data.superseded_by) {
      errors.push(`${file}: status must be "live" or superseded_by: <id>`);
    }
    for (const f of Array.isArray(data.files) ? data.files : []) {
      if (/^['"]/.test(f)) errors.push(`${file}: files entry is quoted: ${f}`);
      else if (!existsSync(join(root, f))) errors.push(`${file}: names a file that does not exist: ${f}`);
    }
    if (data.files && !Array.isArray(data.files)) errors.push(`${file}: "files" must be a list`);
    if (data.triggers && !Array.isArray(data.triggers)) errors.push(`${file}: "triggers" must be a list`);
  }
  for (const p of walk(join(root, 'docs')).filter((p) => p.endsWith('.md'))) {
    if (/^(<{7}|>{7})( |$)/m.test(readFileSync(p, 'utf8'))) errors.push(`${relative(root, p)}: conflict markers`);
  }
  let chars = 0;
  for (const f of ['AGENTS.md', 'CLAUDE.md', 'GEMINI.md', '.github/copilot-instructions.md']) {
    if (existsSync(join(root, f))) chars += readFileSync(join(root, f), 'utf8').length;
  }
  const tokens = Math.round(chars / 3.6);
  if (tokens > 8000) warnings.push(`always-loaded instructions are ~${tokens} tokens; consider trimming`);
  return { errors, warnings, tokens };
}

export function find(root, topic) {
  const t = topic.toLowerCase();
  return lessons(root).filter(({ data }) => data && data.status === 'live' &&
    [data.title, ...(Array.isArray(data.triggers) ? data.triggers : [])].some((s) => String(s).toLowerCase().includes(t)));
}

function index(root) {
  const rows = lessons(root).filter((l) => l.data).map(({ file, data }) =>
    `| ${data.id} | ${data.date} | ${data.session} | [${data.title}](${relative('docs/memory', file).replace(/\\/g, '/')}) | ${(data.triggers || []).join(', ')} | ${data.status} |`);
  const out = ['<!-- GENERATED by `mem index`. Do not edit; re-run on conflict. -->', '# Lesson index', '',
    '| id | date | session | title | triggers | status |', '|---|---|---|---|---|---|', ...rows, ''].join('\n');
  writeFileSync(join(root, 'docs', 'memory', 'INDEX.md'), out);
  return rows.length;
}

function report(root) {
  const dir = join(root, 'docs', 'memory', 'logs');
  const parts = ['<!-- GENERATED by `mem report`. Do not edit; re-run on conflict. -->', '# Last report from each session', ''];
  for (const f of existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.md')).sort() : []) {
    const text = readFileSync(join(dir, f), 'utf8');
    const m = /^##\s[\s\S]*?(?=^##\s|(?![\s\S]))/m.exec(text);
    parts.push(`## ${f.replace(/\.md$/, '')}`, '', m ? m[0].replace(/^##\s+/, '**').replace(/\n/, '**\n') : '_no entries_', '');
  }
  writeFileSync(join(root, 'docs', 'memory', 'LAST_REPORT.md'), parts.join('\n'));
}

// One file per lesson (R7): the session, next id and date are filled in; every field is required.
export function newLesson(root, title, opts) {
  const missing = ['triggers', 'files', 'cost', 'evidence'].filter((k) => !opts[k]);
  if (!title || missing.length) return { error: `need a title and --${missing.join(', --') || 'title'}` };
  const dir = join(root, 'docs', 'memory', 'lessons');
  mkdirSync(dir, { recursive: true });
  const nums = lessons(root).map((l) => parseInt(String((l.data || {}).id || '').replace(/\D/g, ''), 10)).filter((n) => n > 0);
  const id = `L${String((nums.length ? Math.max(...nums) : 0) + 1).padStart(3, '0')}`;
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 48);
  const list = (v) => `[${String(v).split(',').map((x) => x.trim()).filter(Boolean).join(', ')}]`;
  const q = (v) => String(v).replace(/\s*\n\s*/g, ' ');
  const file = join(dir, `${id}-${slug}.md`);
  writeFileSync(file, [
    '---', `id: ${id}`, `date: ${new Date().toISOString().slice(0, 10)}`, `session: ${currentRole(root)}`, `title: ${q(title)}`,
    `triggers: ${list(opts.triggers)}`, `files: ${list(opts.files)}`, `cost: ${q(opts.cost)}`, `evidence: ${q(opts.evidence)}`,
    'status: live', '---', '', opts.body || '', ''].join('\n'));
  return { file: relative(root, file).replace(/\\/g, '/') };
}

function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  const root = process.cwd();
  if (cmd === 'index') console.log(`INDEX.md: ${index(root)} lessons`);
  else if (cmd === 'report') { report(root); console.log('LAST_REPORT.md written'); }
  else if (cmd === 'find' && rest.length) {
    const hits = find(root, rest.join(' '));
    for (const { file, data } of hits) console.log(`${data.id}  ${data.title}\n    cost: ${data.cost}\n    ${file}`);
    if (!hits.length) console.log('no live lesson matches');
  } else if (cmd === 'new') {
    const opts = {}; const words = [];
    for (let i = 0; i < rest.length; i++) { if (rest[i].startsWith('--')) opts[rest[i].slice(2)] = rest[++i]; else words.push(rest[i]); }
    const r = newLesson(root, words.join(' '), opts);
    if (r.error) { console.error(`mem new: ${r.error}`); process.exit(1); }
    console.log(`CREATE  ${r.file} — then \`mem index\` and \`mem check\``);
  } else if (cmd === 'check') {
    const { errors, warnings, tokens } = check(root);
    console.log(`always-loaded instructions: ~${tokens} tokens`);
    for (const w of warnings) console.log(`WARN  ${w}`);
    for (const e of errors) console.log(`ERROR ${e}`);
    console.log(errors.length ? `check FAILED (${errors.length})` : 'check OK');
    process.exit(errors.length ? 1 : 0);
  } else {
    console.log('usage: mem index | mem report | mem find <topic> | mem new "<title>" --triggers … --files … --cost … --evidence … | mem check');
    process.exit(cmd ? 1 : 0);
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] || '').href) main();
